Part 3

# load packages
library(cmdstanr)
library(tidybayes)

# eight-schools data; from my 2nd ed. of BDA on p. 140
est &lt;- c(28, 8, -3, 7, -1, 1, 18, 12)
se_est &lt;- c(15, 10, 16, 11, 9, 11, 10, 18)
J &lt;- length(est)

# the stan model from the script (centered), with the prior scale as data
stan_code_centered &lt;- "
data {
  int&lt;lower=1&gt; J;
  vector[J] est;
  vector&lt;lower=0&gt;[J] se_est;
  real&lt;lower=0&gt; scale;  // scale of the half-cauchy prior on sigma
}
parameters {
  real mu;
  real&lt;lower=0&gt; sigma;
  vector[J] theta;
}
model {
  mu ~ normal(0, 1000);
  sigma ~ cauchy(0, scale);
  theta ~ normal(mu, sigma);
  est ~ normal(theta, se_est);
}
"


model_centered &lt;- cmdstan_model(write_stan_file(stan_code_centered))
fit_centered &lt;- model_centered$sample(
  data = list(J = J, est = est, se_est = se_est, scale = 20),
  seed = 123,
  chains = 4,
  parallel_chains = 4,
  iter_warmup = 2000,
  iter_sampling = 2000
)

# pull the draws and diagnostics into memory (cmdstanr keeps them in temp files)
centered_summary &lt;- fit_centered$summary(variables = c("mu", "sigma"))
centered_diagnostics &lt;- fit_centered$diagnostic_summary()


centered_summary

# A tibble: 2 × 10
  variable  mean median    sd   mad     q5   q95  rhat ess_bulk ess_tail
  &lt;chr&gt;    &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt;    &lt;dbl&gt;    &lt;dbl&gt;
1 mu        7.88   8.08  4.96  4.66 -0.327  15.7  1.00    1426.   2649. 
2 sigma     6.30   5.22  4.64  4.02  1.24   15.0  1.01     249.     75.9

centered_diagnostics

$num_divergent
[1] 65 28 68 18

$num_max_treedepth
[1] 0 0 0 0

$ebfmi
[1] 0.3437584 0.2633397 0.2776665 0.3981525



Divergent transitions in every chain and low E-BFMI. The ESS for sigma is small.
A known problem with this model: when sigma is small, the thetas must sit close to mu, and the sampler can’t move through that region.
The fix is the non-centered parameterization: sample standardized effects z and set theta = mu + sigma * z. Same model, easier posterior.

Part 4

# non-centered version: same model, theta = mu + sigma * z
stan_code_noncentered &lt;- "
data {
  int&lt;lower=1&gt; J;
  vector[J] est;
  vector&lt;lower=0&gt;[J] se_est;
  real&lt;lower=0&gt; scale;  // scale of the half-cauchy prior on sigma
}
parameters {
  real mu;
  real&lt;lower=0&gt; sigma;
  vector[J] z;  // standardized school effects
}
transformed parameters {
  vector[J] theta = mu + sigma * z;
}
model {
  mu ~ normal(0, 1000);
  sigma ~ cauchy(0, scale);
  z ~ std_normal();  // implies theta ~ normal(mu, sigma)
  est ~ normal(theta, se_est);
}
"


model_noncentered &lt;- cmdstan_model(write_stan_file(stan_code_noncentered))

# fit the model for one prior scale; return the draws of sigma and the divergences
fit_scale &lt;- function(scale) {
  fit &lt;- model_noncentered$sample(
    data = list(J = J, est = est, se_est = se_est, scale = scale),
    seed = 123,
    chains = 4,
    parallel_chains = 4,
    iter_warmup = 2000,
    iter_sampling = 2000,
    adapt_delta = 0.95
  )
  tibble(sigma_draws = list(spread_draws(fit, sigma)),
         divergent = sum(fit$diagnostic_summary()$num_divergent))
}

# one row per prior scale
scale_fits &lt;- tibble(scale = c(5, 20, 100)) |&gt;
  mutate(fit = map(scale, fit_scale)) |&gt;
  unnest(fit)


# posterior of sigma for each prior scale
scale_fits |&gt;
  unnest(sigma_draws) |&gt;
  summarize(divergent = first(divergent),
            median = median(sigma),
            q05 = quantile(sigma, 0.05),
            q95 = quantile(sigma, 0.95),
            .by = scale)

# A tibble: 3 × 5
  scale divergent median   q05   q95
  &lt;dbl&gt;     &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt;
1     5         0   2.74 0.236  9.92
2    20         0   4.65 0.480 14.7 
3   100         0   5.21 0.476 16.9 



# posterior densities of sigma
scale_fits |&gt;
  unnest(sigma_draws) |&gt;
  ggplot(aes(x = sigma, color = factor(scale))) +
  geom_density() +
  coord_cartesian(xlim = c(0, 30)) +
  labs(x = "sigma", y = "Posterior density", color = "Scale of the\nhalf-Cauchy prior")









Larger scale, larger sigma: the posterior median and 95th percentile both rise as the scale goes from 5 to 100.
Eight schools say little about sigma, so the prior matters.
Scale 5 pulls sigma toward zero and the school effects toward mu. Scale 100 lets them spread out.
